mapper.select:
SELECT m.major_id AS majorId, m.name AS name, COUNT(DISTINCT e.user_id) AS employeeCount, COUNT(DISTINCT ee.user_id) AS referenceCount FROM major m LEFT JOIN employee_education ee ON ee.major_id = m.major_id AND ee.company_id = #{companyId} LEFT JOIN employee e ON e.user_id = ee.user_id AND e.company_id = #{companyId} AND e.is_system = 0 AND e.deleted_at IS NULL AND e.resigned_at IS NULL WHERE m.company_id = #{companyId}
AND m.name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY m.major_id, m.name ORDER BY m.name

SELECT COUNT(DISTINCT ee.user_id)
  FROM employee_education ee
 WHERE ee.major_id = #{majorId} AND ee.company_id = #{companyId}
